var CryptoJS = require('crypto-js')



function get_ming(e) {
    const Hu = "asdASE123854kjsd"
    const Tg = CryptoJS.enc.Utf8.parse(Hu)
    const zA = CryptoJS.enc.Utf8.parse(Hu)
    const Dg = {
        iv: zA,
        mode: CryptoJS.mode.CBC,
        padding: CryptoJS.pad.Pkcs7
    };
    const t = CryptoJS.enc.Hex.parse(e)
        , n = CryptoJS.enc.Base64.stringify(t)
        , o = CryptoJS.AES.decrypt(n, Tg, Dg).toString(CryptoJS.enc.Utf8);
    return JSON.parse(o.toString())
}

